{\sc[Ear Decomposition Theorem]}\\
    A bipartite graph is matching covered if and only if it admits an ear decomposition.
    \label{thm : odd ear decomp}

{\sc[Main Theorem: Characterization of $\mathcal{H}_2$]}\\
    A graph is a $2$-vertex extremal{} minimal bipartite matching covered graph{} if and only if it is obtained from a Halin tree{} by isomorphic leaf matching{}.
    \label{thm : evm}

{\sc[Characterization of $\mathcal{H}_3$]}\\
    A graph is a $2$-vertex $n$-extremal{} minimal bipartite matching covered graph{} if and only if it is obtained from a cubic Halin tree{} by isomorphic leaf matching{}.
    \label{thm : evn}

{\sc[Characterization of $\mathcal{H}_4$]}\\
    A graph is an edge extremal{} minimal bipartite matching covered graph{} if and only if it is obtained from a star by isomorphic leaf matching{}.
    \label{thm : ee}

Any graph $G$ obtained from a Halin tree{} $T$ by isomorphic leaf matching{} is a minimal bipartite matching covered graph{} that is $2$-vertex extremal{}. Furthermore:
    \begin{enumerate}

        \item if $T$ is a cubic Halin tree{} then $G$ is also $2$-vertex $n$-extremal{}, whereas
        \item if $T$ is a star then $G$ is also edge extremal{}. 
    \end{enumerate}
    \label{thm : embmcg TcupT'}

{\sc[Characterization of $\mathcal{H}_0$]}\\
    A graph $G$, distinct from $C_4$, is a $2$-edge extremal{} minimal bipartite matching covered graph{} if and only if its partial retract{} $\widehat{G}$ is a $2$-vertex extremal{} minimal bipartite matching covered graph{}.
    \label{thm : eem}

{\sc[Characterization of $\mathcal{H}_1$]}\\
    A graph $G$ is a $2$-edge $n$-extremal{} minimal bipartite matching covered graph{} if and only if its partial retract{} $\widehat{G}$ is an edge extremal{} minimal bipartite matching covered graph{} and $\Delta(G)=3$.
    \label{thm : een}

Every extremal minimal bipartite matching covered graph{}, distinct from $C_4$, satisfies the following:
    \begin{enumerate}
        \item $E_2$ is a perfect matching of $G[V_2]$ and $|E_2|=m-n+2$,
        \item each ear in any ear decomposition has exactly one $2$-edge, and
        \item each conformal cycle has precisely two $2$-edges.



    \end{enumerate}

    \label{lem : basic prop of embmcg}

Every extremal minimal bipartite matching covered graph{}, distinct from $C_4$, satisfies the following:
    \begin{enumerate}



        \item $|V_3|=3n-2m-4$,
        \item $|E_{3,2}|=2m-2n+4$, and 
        \item $|E_{3}|=3n-2m-6=|V_3|-2$.\hfill{$\qed$}        
    \end{enumerate}

    \label{cor : counting prop of embmcg}

{\sc[Balanced $2$-cut Property]}\\
    In an extremal minimal bipartite matching covered graph{}, each \mbox{$3$-edge}{} participates in a balanced $2$-cut with some other \mbox{$3$-edge}{}.
    \label{thm : 2-cut property}

{\sc [Balanced $2$-cut Induction Tool]}\\
    Let $G$ be a bipartite graph that has a balanced $2$-cut $F$, and let $G_1$ and $G_2$ be the (bipartite) graphs obtained from $G$ by a $2$-cut decomposition across $F$. Then the following statements hold:
    \begin{enumerate}
        \item $G$ is matching covered{} if and only if $G_1$ and $G_2$ are both matching covered{};
        \item furthermore, $G$ is minimal if and only if $G_1$ and $G_2$ are both minimal; and
        \item finally, $G$ is extremal if and only if $G_1$ and $G_2$ are both extremal.
    \end{enumerate}
    \label{thm : 2-cut induction tool}

{\sc [Bicontraction preserves Matching Covered property]}\\
    Let $G$ be a graph that has a vertex of degree two, say $v$, that has two distinct neighbours each of which has degree two or more, and let $G':=G/v$. Then $G$ is matching covered{} if and only if $G'$ is matching covered{}.\qed
    \label{lem : bicontraction preserves mc}

{\sc [Restricted Bicontraction preserves $2$-edge Extremality]}\\
    Let $G$ be a bipartite graph that has a vertex of degree two, say $v$, each of whose neighbours has degree three or more, and let $G':=G/v$. Then the following statements hold:
    \begin{enumerate}
        \item $G$ is matching covered{} if and only if $G'$ is matching covered{};
        \item furthermore, $G$ is minimal if and only if $G'$ is minimal; and
        \item finally, $G$ belongs to $\mathcal{H}_0$ if and only if $G'$ belongs to $\mathcal{H}_0$.
    \end{enumerate}
    \label{thm : bicontraction preserves extremality}

{\sc[Characterization of \mbox{$k$-extendable} Bipartite Graphs]}\\
For a bipartite graph $G[A,B]$ of order at least $2k+2$, where $|A|=|B|$, the following are equivalent:
\begin{enumerate}
    \item $G$ is $k$-extendable, 
    \item for every nonempty subset $S\subseteq A$, either $N(S)=B$ or $|N(S)|\geqslant |S|+k$, and
    \item $G-X-Y$ is matchable for all $X\subseteq A$ and $Y\subseteq B$ such that $|X|=|Y|=k$.
\end{enumerate}
\label{thm : k-extendability characterization}

{\sc[Main Conjecture]}\\
    In a minimal \mbox{$k$-extendable} bipartite graph, $|V_{k+1}|\geqslant \frac{2}{2k-1}(m-n+2k)$.                                                                                            
    \label{conj : evm}

An edge $e$ of a \mbox{$k$-extendable} bipartite graph is not superfluous{} if either of the following holds:
\begin{enumerate}
    \item either an end of $e$ has degree $k+1$,
    \item or $e$ belongs to a nontrivial $2k$-cut. \qed
\end{enumerate}
\label{cor : superfluous edge}

{\sc[Isomorphic $k$-leaf Matching]}\\
Let $T$ denote a nontrivial tree, and $L$ its set of leaves. For a positive integer $k$, let $H$ denote the (bipartite) graph obtained from the disjoint union of $k$ copies of $T$, say $T_1,T_2,\dots T_k$, by identifying, for each member of $L$,  all of its $k$ copies into a single vertex; we let $L(H):=L$. Now, let $H'$ denote a copy of $H$. The (bipartite) graph $G$ obtained from $H\cup H'$ by adding a matching, each of whose edges joins a member of $L(H)$ with the corresponding member of $L(H')$ as per some fixed isomorphism between $H$ and $H'$, is said to be obtained from $T$ by \textit{isomorphic \mbox{$k$-leaf} matching}; furthermore, we let $L(G):=L(H)\cup L(H')$.
\label{defn : kisojoin}

For a positive integer $k$, any graph $G$ obtained from a $(k+2)$-tree $T$, that is neither $K_2$ nor a star $K_{1,p}$ where $p< 2k$, by isomorphic \mbox{$k$-leaf} matching is a minimal \mbox{$k$-extendable} bipartite graph that satisfies the bound in Conjecture~\ref{conj : evm} with equality. Furthermore:
    \begin{enumerate}

        \item if $T$ is a regular $(k+2)$-tree then $G$ satisfies the bound in Conjecture~\ref{conj : evn} with equality, whereas
        \item if $T$ is a star then $G$ satisfies the bound in Conjecture~\ref{conj : ee} with equality. 
    \end{enumerate}
    \label{thm : proof for tight examples}
